css:
.rail{display:flex;gap:20px;overflow-x:auto;scroll-snap-type:x proximity;
  margin-right:calc(50% - 50vw); /* 片端型：右だけ画面外へ抜く */
  padding-right:0;scrollbar-width:none}
.rail::-webkit-scrollbar{display:none}
.rail>*{flex:0 0 clamp(200px,24%,320px);scroll-snap-align:start}

/* 両端型（左右とも切る） */
.rail--both{margin-inline:calc(50% - 50vw);padding-inline:0}
.rail--both>*{flex:0 0 22%;scroll-snap-align:center}
